package com.nm.fragmentsclean.editorialIntelligenceContext.write.adapters.secondary.gateways.repositories;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.nm.fragmentsclean.editorialIntelligenceContext.write.businesslogic.gateways.TopicCandidateRepository;
import com.nm.fragmentsclean.editorialIntelligenceContext.write.businesslogic.models.*;
import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Repository; import java.sql.Timestamp;
@Repository public final class JdbcTopicCandidateRepository implements TopicCandidateRepository { private final JdbcTemplate jdbc; private final ObjectMapper json; public JdbcTopicCandidateRepository(JdbcTemplate jdbc,ObjectMapper json){this.jdbc=jdbc;this.json=json;} public void save(TopicCandidate c){var s=c.snapshot();try{jdbc.update("INSERT INTO editorial_topic_candidates(topic_candidate_id,subject,suggested_angle,signal_ids_json,detected_at,status) VALUES(?,?,?,?,?,?) ON CONFLICT(topic_candidate_id) DO UPDATE SET status=EXCLUDED.status",s.id(),s.subject(),s.suggestedAngle(),json.writeValueAsString(s.signalIds()),Timestamp.from(s.detectedAt()),s.status().name());}catch(Exception e){throw new IllegalStateException("Could not persist topic candidate",e);}} public java.util.Optional<TopicCandidate> byId(java.util.UUID id){try{return java.util.Optional.ofNullable(jdbc.queryForObject("SELECT topic_candidate_id,subject,suggested_angle,signal_ids_json,detected_at,status FROM editorial_topic_candidates WHERE topic_candidate_id=?",(rs,row)->{try{var ids=java.util.List.of(json.readValue(rs.getString("signal_ids_json"),java.util.UUID[].class));return TopicCandidate.reconstitute(new TopicCandidate.Snapshot(rs.getObject("topic_candidate_id",java.util.UUID.class),rs.getString("subject"),rs.getString("suggested_angle"),ids,rs.getTimestamp("detected_at").toInstant(),TopicCandidateStatus.valueOf(rs.getString("status"))));}catch(Exception e){throw new IllegalStateException("Invalid persisted topic candidate",e);}},id));}catch(org.springframework.dao.EmptyResultDataAccessException e){return java.util.Optional.empty();}} }
